package com.nigson.acceptance.carrier;
import java.util.*;
import java.time.*;
import com.nigson.commerce.fulfillment.*;
import com.nigson.commerce.files.*;
import com.nigson.commerce.platform.*;
import com.nigson.acceptance.fulfillment.ShipmentFixture;
import com.nigson.acceptance.files.StorageFixture;
import com.nigson.shared.security.PrivateWorkload;
import com.nigson.shared.events.EventCodec;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import static org.assertj.core.api.Assertions.*;
/** Actual TLS/SigV4 private storage and owned PostgreSQL; never a canned label HEAD. */
class CarrierResultPersistenceTest {
 ShipmentFixture f;StorageFixture storage;CarrierResultService service;FulfillmentValues.Shipment shipment;JdbcTemplate jdbc;org.springframework.transaction.PlatformTransactionManager manager;io.micrometer.core.instrument.simple.SimpleMeterRegistry metrics;
 @BeforeEach void setup()throws Exception{String url=System.getenv("NIGSON_TEST_JDBC_URL"),fixture=System.getenv("NIGSON_TEST_CARRIER_STORAGE_FIXTURE");Assumptions.assumeTrue(url!=null&&fixture!=null,"carrier-check supplies isolated database/TLS storage");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");manager=new DataSourceTransactionManager(ds);jdbc=new JdbcTemplate(ds);f=new ShipmentFixture(jdbc,manager);CarrierContextPersistenceTest.freeze(f);shipment=f.create("5","FEDEX",null,"result-intent");storage=new StorageFixture(fixture);metrics=new io.micrometer.core.instrument.simple.SimpleMeterRegistry();service=service(storage.storage);}
 CarrierResultService service(FileStorage port){var clock=Clock.systemUTC();return new CarrierResultService(jdbc,f.repository,port,new FulfillmentPolicy(true,"test","MOCK","SYNTHETIC_LABEL_NOT_QUALIFIED",Instant.now().plusSeconds(3600),"",Set.of("tracking.synthetic.invalid"),clock),new PlatformStore(jdbc,manager,clock,metrics),new AuditWriter(jdbc,clock,metrics),manager,clock,"test",metrics);}
 @AfterEach void cleanup(){if(f!=null)f.close();if(storage!=null)storage.close();if(metrics!=null)metrics.close();}
 static PrivateWorkload.Proof proof(){return new PrivateWorkload.Proof("nigson-integration","synthetic-provider-result",PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-120")).findFirst().orElseThrow(),null);}
 String booking(){return jdbc.queryForObject("SELECT booking_request_id::text FROM commerce.shipment WHERE id=?",String.class,shipment.id());}
 CarrierResultValues.Result label(UUID command,String owner)throws Exception{return putLabel(storage,shipment.id(),command,owner);}
 static CarrierResultValues.Result putLabel(StorageFixture storage,UUID shipment,UUID command,String owner)throws Exception{
  var pdf=new java.io.ByteArrayOutputStream();pdf.writeBytes("%PDF-1.4\n".getBytes(java.nio.charset.StandardCharsets.US_ASCII));var offsets=new ArrayList<Integer>();for(String object:List.of("<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 288 432] /Resources << >> >>")){offsets.add(pdf.size());pdf.writeBytes((offsets.size()+" 0 obj\n"+object+"\nendobj\n").getBytes(java.nio.charset.StandardCharsets.US_ASCII));}int cross=pdf.size();pdf.writeBytes("xref\n0 4\n0000000000 65535 f \n".getBytes(java.nio.charset.StandardCharsets.US_ASCII));for(int offset:offsets)pdf.writeBytes(String.format(java.util.Locale.ROOT,"%010d 00000 n \n",offset).getBytes(java.nio.charset.StandardCharsets.US_ASCII));pdf.writeBytes(("trailer\n<< /Size 4 /Root 1 0 R >>\nstartxref\n"+cross+"\n%%EOF\n").getBytes(java.nio.charset.StandardCharsets.US_ASCII));byte[] bytes=pdf.toByteArray();String checksum=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));String key="test/commerce/shipping_label/"+shipment+"/0/pdf";UUID asset=UUID.randomUUID();var signed=storage.storage.upload(asset,key,new FileValues.Upload("SHIPPING_LABEL","synthetic.pdf","application/pdf",bytes.length,checksum,shipment,"pdf"),owner,Instant.now());assertThat(storage.put(new FileValues.UploadResult(asset,signed.url(),signed.headers(),signed.expiresAt()),bytes).statusCode()).isEqualTo(200);var source=storage.storage.quarantine(key);storage.storage.promote(key,source.version(),source.etag(),key,true);return new CarrierResultValues.Result(command,"FEDEX","123456789012","READY",Instant.now(),null,key,checksum,"BOOKED","MOCK");
 }
 CarrierResultValues.Result tracking(String state,Instant time){return new CarrierResultValues.Result(UUID.randomUUID(),"FEDEX","123456789012",state,time,null,null,null,null,"MOCK");}
 @Test void privateBookedLabelAcknowledgementIsAtomicAndReplayAvoidsHttp()throws Exception{var input=label(UUID.randomUUID(),booking());int heads=storage.control(null).path("heads").asInt();var ready=service.accept(proof(),shipment.id(),input,UUID.randomUUID());assertThat(ready.status()).isEqualTo("READY");assertThat(f.value("on_hand")).isEqualByComparingTo("10");assertThat(f.value("allocated")).isEqualByComparingTo("5");assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.asset_reference WHERE shipment_id=? AND purpose='SHIPPING_LABEL' AND classification='PRIVATE' AND status='CLEAN'",Integer.class,shipment.id())).isEqualTo(1);int after=storage.control(null).path("heads").asInt();assertThat(after).isEqualTo(heads+1);assertThat(service.accept(proof(),shipment.id(),input,UUID.randomUUID())).isEqualTo(ready);assertThat(storage.control(null).path("heads").asInt()).isEqualTo(after);assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='SHIPMENT_PROVIDER_RESULT'",Integer.class,shipment.id())).isEqualTo(1);}
 @Test void unknownNeverBecomesReadyAndProviderTransitCannotDebitStock()throws Exception{var unknown=new CarrierResultValues.Result(UUID.randomUUID(),"FEDEX",booking(),"EXCEPTION",Instant.now(),null,null,null,"UNKNOWN","MOCK");assertThat(service.accept(proof(),shipment.id(),unknown,UUID.randomUUID()).status()).isEqualTo("EXCEPTION");var input=label(UUID.randomUUID(),booking());var ready=service.accept(proof(),shipment.id(),input,UUID.randomUUID());assertThat(ready.status()).isEqualTo("READY");assertThat(service.accept(proof(),shipment.id(),tracking("SHIPPED",Instant.now()),UUID.randomUUID()).status()).isEqualTo("READY");assertThatThrownBy(()->service.accept(proof(),shipment.id(),tracking("DELIVERED",Instant.now()),UUID.randomUUID())).hasMessage("INVALID_TRANSITION");assertThat(f.value("on_hand")).isEqualByComparingTo("10");assertThat(f.value("allocated")).isEqualByComparingTo("5");}
 @Test void trackingDeliveryFollowsExplicitPhysicalHandoverAndCannotRegress()throws Exception{var input=label(UUID.randomUUID(),booking());var ready=service.accept(proof(),shipment.id(),input,UUID.randomUUID());var shipped=f.service.dispatch(f.inventory.actor,shipment.id(),ready.version(),"Synthetic actual physical handover","result-dispatch",UUID.randomUUID());assertThat(shipped.status()).isEqualTo("SHIPPED");Instant delivered=Instant.now();assertThat(service.accept(proof(),shipment.id(),tracking("DELIVERED",delivered),UUID.randomUUID()).status()).isEqualTo("DELIVERED");assertThat(service.accept(proof(),shipment.id(),tracking("SHIPPED",delivered.minusSeconds(1)),UUID.randomUUID()).status()).isEqualTo("DELIVERED");assertThat(f.value("on_hand")).isEqualByComparingTo("5");assertThat(f.value("allocated")).isZero();assertThat(jdbc.queryForObject("SELECT payment_status FROM commerce.sales_order WHERE id=?",String.class,f.order)).isEqualTo("PAID");}
 @Test void wrongBookingMetadataCannotCreateCleanLabel()throws Exception{var input=label(UUID.randomUUID(),UUID.randomUUID().toString());assertThatThrownBy(()->service.accept(proof(),shipment.id(),input,UUID.randomUUID())).hasMessage("FULFILLMENT_RULE_VIOLATION");assertThat(f.repository.find(shipment.id(),false).status()).isEqualTo("CREATED");assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.asset_reference WHERE shipment_id=?",Integer.class,shipment.id())).isZero();}
 @Test void auditFailureRollsBackLabelStateHistoryAndAcknowledgement()throws Exception{var input=label(UUID.randomUUID(),booking());f.inventory.admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->service.accept(proof(),shipment.id(),input,UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);}finally{f.inventory.admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}assertThat(f.repository.find(shipment.id(),false).status()).isEqualTo("CREATED");assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.asset_reference WHERE shipment_id=?",Integer.class,shipment.id())).isZero();assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.shipment_event WHERE shipment_id=? AND source='FEDEX'",Integer.class,shipment.id())).isZero();assertThat(service.accept(proof(),shipment.id(),input,UUID.randomUUID()).status()).isEqualTo("READY");}
 @Test void twelveConcurrentDuplicateAcknowledgementsHaveOneLocalEffect()throws Exception{var input=label(UUID.randomUUID(),booking());try(var pool=java.util.concurrent.Executors.newFixedThreadPool(12)){var start=new java.util.concurrent.CountDownLatch(1);var tasks=new ArrayList<java.util.concurrent.Future<Object>>();for(int n=0;n<12;n++)tasks.add(pool.submit(()->{start.await();try{return service.accept(proof(),shipment.id(),input,UUID.randomUUID());}catch(PlatformStore.Conflict|com.nigson.shared.problem.Problem.Failure failure){return failure.getMessage();}}));start.countDown();for(var task:tasks){var result=task.get(20,java.util.concurrent.TimeUnit.SECONDS);if(result instanceof FulfillmentValues.Shipment accepted)assertThat(accepted.status()).isEqualTo("READY");else assertThat(result).isEqualTo("IDEMPOTENCY_IN_PROGRESS");}}assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.asset_reference WHERE shipment_id=?",Integer.class,shipment.id())).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.shipment_event WHERE shipment_id=? AND source='FEDEX'",Integer.class,shipment.id())).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='SHIPMENT_PROVIDER_RESULT'",Integer.class,shipment.id())).isEqualTo(1);assertThat(f.value("on_hand")).isEqualByComparingTo("10");}
 @Test void acceptedBookingTruthSurvivesRefundingButCannotAuthorizeDispatch()throws Exception{var input=label(UUID.randomUUID(),booking());jdbc.update("UPDATE commerce.sales_order SET status='REFUNDING' WHERE id=?",f.order);var ready=service.accept(proof(),shipment.id(),input,UUID.randomUUID());assertThat(ready.status()).isEqualTo("READY");assertThatThrownBy(()->f.service.dispatch(f.inventory.actor,shipment.id(),ready.version(),"Synthetic forbidden refunding handover","deny-refunding",UUID.randomUUID())).hasMessage("FULFILLMENT_RULE_VIOLATION");assertThat(jdbc.queryForObject("SELECT status FROM commerce.sales_order WHERE id=?",String.class,f.order)).isEqualTo("REFUNDING");assertThat(jdbc.queryForObject("SELECT payment_status FROM commerce.sales_order WHERE id=?",String.class,f.order)).isEqualTo("PAID");assertThat(f.value("on_hand")).isEqualByComparingTo("10");assertThat(f.value("allocated")).isEqualByComparingTo("5");}

 @Test void privateLabelDownloadRequiresCurrentOperationsRole()throws Exception{var input=label(UUID.randomUUID(),booking());service.accept(proof(),shipment.id(),input,UUID.randomUUID());UUID asset=jdbc.queryForObject("SELECT label_asset_id FROM commerce.shipment WHERE id=?",UUID.class,shipment.id());var clock=Clock.systemUTC();var files=new FileService(new JdbcFileRepository(jdbc,clock),storage.storage,new PlatformStore(jdbc,manager,clock,metrics),new AuditWriter(jdbc,clock,metrics),manager,clock,"test",metrics);var download=files.download(f.inventory.actor,asset,UUID.randomUUID());assertThat(java.time.Duration.between(Instant.now(),download.expiresAt()).toSeconds()).isBetween(58L,60L);assertThat(storage.get(download.url()).statusCode()).isEqualTo(200);jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=? AND role='OPERATIONS'",f.inventory.actor.party());assertThatThrownBy(()->files.download(f.inventory.actor,asset,UUID.randomUUID())).hasMessage("ACCESS_DENIED");}

 @Test void modePrefixAndChecksumMismatchCannotRegisterLabel()throws Exception{var valid=label(UUID.randomUUID(),booking());int heads=storage.control(null).path("heads").asInt();var mode=new CarrierResultValues.Result(UUID.randomUUID(),"FEDEX",valid.reference(),"READY",valid.occurredAt(),null,valid.labelObjectKey(),valid.labelChecksum(),"BOOKED","LIVE");assertThatThrownBy(()->service.accept(proof(),shipment.id(),mode,UUID.randomUUID())).hasMessage("PROVIDER_MODE_MISMATCH");var prefix=new CarrierResultValues.Result(UUID.randomUUID(),"FEDEX",valid.reference(),"READY",valid.occurredAt(),null,"test/commerce/shipping_label/"+UUID.randomUUID()+"/0/pdf",valid.labelChecksum(),"BOOKED","MOCK");assertThatThrownBy(()->service.accept(proof(),shipment.id(),prefix,UUID.randomUUID())).hasMessage("FULFILLMENT_RULE_VIOLATION");assertThat(storage.control(null).path("heads").asInt()).isEqualTo(heads);var checksum=new CarrierResultValues.Result(UUID.randomUUID(),"FEDEX",valid.reference(),"READY",valid.occurredAt(),null,valid.labelObjectKey(),"0".repeat(64),"BOOKED","MOCK");assertThatThrownBy(()->service.accept(proof(),shipment.id(),checksum,UUID.randomUUID())).hasMessage("FULFILLMENT_RULE_VIOLATION");assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.asset_reference WHERE shipment_id=?",Integer.class,shipment.id())).isZero();assertThat(f.repository.find(shipment.id(),false).status()).isEqualTo("CREATED");}

 @Test void malformedActualStorageHeadUsesEndpointSafeErrorAndNeverMarksClean()throws Exception{var input=label(UUID.randomUUID(),booking());storage.control("INVALID_HEAD_CHECKSUM");assertThatThrownBy(()->service.accept(proof(),shipment.id(),input,UUID.randomUUID())).hasMessage("FULFILLMENT_RULE_VIOLATION");assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.asset_reference WHERE shipment_id=?",Integer.class,shipment.id())).isZero();assertThat(f.repository.find(shipment.id(),false).status()).isEqualTo("CREATED");assertThat(service.accept(proof(),shipment.id(),input,UUID.randomUUID()).status()).isEqualTo("READY");}

 @Test void lateRecordedPhysicalHandoverAcceptsOriginalEarlierDeliveryScanWithoutRewritingIt()throws Exception{var ready=service.accept(proof(),shipment.id(),label(UUID.randomUUID(),booking()),UUID.randomUUID());Instant actual=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);java.util.concurrent.TimeUnit.MILLISECONDS.sleep(5);Instant delivered=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);var original=tracking("DELIVERED",delivered);assertThatThrownBy(()->service.accept(proof(),shipment.id(),original,UUID.randomUUID())).hasMessage("INVALID_TRANSITION");var shipped=f.service.dispatch(f.inventory.actor,shipment.id(),ready.version(),"Synthetic late recorded physical handover",actual,"late-physical",UUID.randomUUID());assertThat(shipped.status()).isEqualTo("SHIPPED");assertThat(jdbc.queryForObject("SELECT dispatched_at FROM commerce.shipment WHERE id=?",java.sql.Timestamp.class,shipment.id()).toInstant()).isEqualTo(actual);assertThat(jdbc.queryForObject("SELECT occurred_at FROM commerce.shipment_event WHERE shipment_id=? AND source='OPERATIONS' AND status='SHIPPED'",java.sql.Timestamp.class,shipment.id()).toInstant()).isEqualTo(actual);var event=com.nigson.shared.events.EventCodec.JSON.readTree(jdbc.queryForObject("SELECT payload::text FROM commerce.outbox_event WHERE aggregate_id=? AND event_type='shipment.changed.v1' AND payload->'payload'->>'status'='SHIPPED'",String.class,shipment.id()));assertThat(Instant.parse(event.path("payload").path("occurred_at").asString())).isEqualTo(actual);assertThat(Instant.parse(event.path("occurred_at").asString())).isAfterOrEqualTo(delivered);assertThat(service.accept(proof(),shipment.id(),original,UUID.randomUUID()).status()).isEqualTo("DELIVERED");assertThat(jdbc.queryForObject("SELECT delivered_at FROM commerce.shipment WHERE id=?",java.sql.Timestamp.class,shipment.id()).toInstant()).isEqualTo(delivered);assertThat(f.service.dispatch(f.inventory.actor,shipment.id(),ready.version(),"Synthetic late recorded physical handover",actual,"late-physical",UUID.randomUUID())).isEqualTo(shipped);assertThatThrownBy(()->f.service.dispatch(f.inventory.actor,shipment.id(),ready.version(),"Synthetic late recorded physical handover",actual.plusNanos(1000),"late-physical",UUID.randomUUID())).hasMessage("IDEMPOTENCY_HASH_MISMATCH");assertThat(f.value("on_hand")).isEqualByComparingTo("5");assertThat(f.value("allocated")).isZero();}
 @Test void futureAndPreCreationHandoverCannotMoveStockOrChangeShipment()throws Exception{var ready=service.accept(proof(),shipment.id(),label(UUID.randomUUID(),booking()),UUID.randomUUID());Instant created=jdbc.queryForObject("SELECT created_at FROM commerce.shipment WHERE id=?",java.sql.Timestamp.class,shipment.id()).toInstant();int n=0;for(Instant invalid:List.of(Instant.now().plusSeconds(60),created.minusNanos(1000))){String key="invalid-physical-"+(n++);assertThatThrownBy(()->f.service.dispatch(f.inventory.actor,shipment.id(),ready.version(),"Synthetic invalid physical handover",invalid,key,UUID.randomUUID())).hasMessage("FULFILLMENT_RULE_VIOLATION");}assertThat(f.repository.find(shipment.id(),false).status()).isEqualTo("READY");assertThat(f.value("on_hand")).isEqualByComparingTo("10");assertThat(f.value("allocated")).isEqualByComparingTo("5");}

}
